/// <summary>
/// Represents a YubiKey OTP slot (1 or 2).
/// </summary>
public enum Slot
{
    One = 1,
    Two = 2
}

/// <summary>
/// Extension methods for mapping <see cref="Slot"/> to <see cref="ConfigSlot"/> values.
/// </summary>
public static class SlotExtensions
{
    /// <summary>
    /// Maps a <see cref="Slot"/> to the corresponding <see cref="ConfigSlot"/> for a given operation type.
    /// </summary>
    public static ConfigSlot Map(this Slot slot, SlotOperation operation) =>
        (slot, operation) switch
        {
            (Slot.One, SlotOperation.Configure) => ConfigSlot.Config1,
            (Slot.Two, SlotOperation.Configure) => ConfigSlot.Config2,
            (Slot.One, SlotOperation.Update) => ConfigSlot.Update1,
            (Slot.Two, SlotOperation.Update) => ConfigSlot.Update2,
            (Slot.One, SlotOperation.Ndef) => ConfigSlot.Ndef1,
            (Slot.Two, SlotOperation.Ndef) => ConfigSlot.Ndef2,
            (Slot.One, SlotOperation.ChallengeHmac) => ConfigSlot.ChalHmac1,
            (Slot.Two, SlotOperation.ChallengeHmac) => ConfigSlot.ChalHmac2,
            (Slot.One, SlotOperation.ChallengeYubicoOtp) => ConfigSlot.ChalYubico1,
            (Slot.Two, SlotOperation.ChallengeYubicoOtp) => ConfigSlot.ChalYubico2,
            _ => throw new ArgumentOutOfRangeException(nameof(slot), slot, "Invalid slot or operation.")
        };
}

/// <summary>
/// The type of slot operation to perform.
/// </summary>
public enum SlotOperation
{
    Configure,
    Update,
    Ndef,
    ChallengeHmac,
    ChallengeYubicoOtp
}

/// <summary>
/// Encodes the OTP protocol command/slot byte sent to the YubiKey.
/// These values are used as P1 in SmartCard APDUs or as the slot byte in OTP HID frames.
/// </summary>
public enum ConfigSlot : byte
{
    Config1 = 0x01,
    Config2 = 0x03,
    Update1 = 0x04,
    Update2 = 0x05,
    Swap = 0x06,
    Ndef1 = 0x08,
    Ndef2 = 0x09,
    DeviceSerial = 0x10,
    ScanMap = 0x12,
    ChalYubico1 = 0x20,
    ChalYubico2 = 0x28,
    ChalHmac1 = 0x30,
    ChalHmac2 = 0x38
}

/// <summary>
/// Configures a slot for HMAC-SHA1 challenge-response mode.
/// </summary>
/// <remarks>
/// The 20-byte HMAC key is split across the wire format:
/// <list type="bullet">
/// <item>Bytes 0–15 are stored in the <c>key</c> field (16 bytes)</item>
/// <item>Bytes 16–19 are stored in <c>uid[0..4]</c> (4 bytes)</item>
/// </list>
/// The key must be exactly 20 bytes. Keys of any other length are rejected
/// before any device I/O is attempted; they are never hashed or padded to fit.
/// </remarks>
public sealed class HmacSha1SlotConfiguration : SlotConfiguration
{
    /// <summary>
    /// Initializes a new HMAC-SHA1 challenge-response configuration.
    /// </summary>
    /// <param name="hmacKey">
    /// The HMAC-SHA1 secret key. Must be exactly <see cref="YubiOtpConstants.HmacKeySize"/> (20) bytes.
    /// </param>
    /// <exception cref="ArgumentException">
    /// Thrown when the key is not exactly 20 bytes.
    /// </exception>
    public HmacSha1SlotConfiguration(ReadOnlySpan<byte> hmacKey)
    {
        SetHmacKey(hmacKey, 0);

        _tktFlags |= TicketFlag.ChalResp;
        _cfgFlags |= ConfigFlag.ChalHmac | ConfigFlag.HmacLt64;
    }

    /// <summary>
    /// Configures an OATH token ID prefix for the HOTP output.
    /// </summary>
    /// <param name="tokenId">The raw token ID value (up to 16 bytes).</param>
    /// <param name="fixedModhex1">Output the first byte of the token ID as modhex.</param>
    /// <param name="fixedModhex2">Output the first two bytes of the token ID as modhex.</param>
    /// <returns>This configuration for chaining.</returns>
    /// <remarks>
    /// If both <paramref name="fixedModhex1"/> and <paramref name="fixedModhex2"/> are set,
    /// the entire token ID is sent as modhex.
    /// </remarks>
    public HotpSlotConfiguration TokenId(
        ReadOnlySpan<byte> tokenId,
        bool fixedModhex1 = false,
        bool fixedModhex2 = false)
    {
        if (tokenId.Length > YubiOtpConstants.FixedSize)
        {
            throw new ArgumentException(
                $"Token ID must be at most {YubiOtpConstants.FixedSize} bytes.",
                nameof(tokenId));
        }

        SetFixed(tokenId);
        SetCfgFlag(ConfigFlag.OathFixedModhex1, fixedModhex1);
        SetCfgFlag(ConfigFlag.OathFixedModhex2, fixedModhex2);
        return this;
    }
}

/// <summary>
/// Configures a slot for static password mode using keyboard scan codes.
/// </summary>
/// <remarks>
/// Scan codes are distributed across the 38-byte area (fixed + uid + key):
/// <list type="bullet">
/// <item><c>fixed[0..16]</c> — first 16 scan code bytes</item>
/// <item><c>uid[0..6]</c> — scan code bytes 16–21</item>
/// <item><c>key[0..16]</c> — scan code bytes 22–37</item>
/// </list>
/// </remarks>
public sealed class StaticPasswordSlotConfiguration : KeyboardSlotConfiguration
{
    /// <summary>
    /// Initializes a new static password configuration from a human-readable password,
    /// translating each character to a HID scan code for the given keyboard layout.
    /// </summary>
    /// <remarks>
    /// The YubiKey itself has no concept of a keyboard layout; it only emits HID scan
    /// codes over USB. The scan codes produced here will render as <paramref name="password"/>
    /// only on a host configured with the same <paramref name="keyboardLayout"/>. Use
    /// <see cref="KeyboardLayout.ModHex"/> for a layout-independent password.
    /// </remarks>

/// <summary>
/// Configures a slot for static ticket mode. This generates a fixed, unchanging
/// ticket using the configured key material.
/// </summary>
/// <remarks>
/// Wire format layout mirrors Yubico OTP:
/// <list type="bullet">
/// <item><c>fixed[0..publicId.Length]</c> — public identity prefix (up to 16 bytes)</item>
/// <item><c>uid</c> — 6-byte private identity</item>
/// <item><c>key</c> — 16-byte AES-128 key</item>
/// </list>
/// The <see cref="ConfigFlag.StaticTicket"/> flag is set to produce a non-incrementing ticket.
/// </remarks>
public sealed class StaticTicketSlotConfiguration : KeyboardSlotConfiguration
{
    /// <summary>
    /// Initializes a new static ticket configuration.
    /// </summary>
    /// <param name="publicId">
    /// The public identity prefix (up to 16 bytes).
    /// </param>
    /// <param name="privateId">The 6-byte private identity.</param>
    /// <param name="aesKey">The 16-byte AES-128 key.</param>
    /// <exception cref="ArgumentException">
    /// Thrown when <paramref name="publicId"/> exceeds 16 bytes,
    /// <paramref name="privateId"/> is not 6 bytes, or
    /// <paramref name="aesKey"/> is not 16 bytes.
    /// </exception>
    public StaticTicketSlotConfiguration(
        ReadOnlySpan<byte> publicId,
        ReadOnlySpan<byte> privateId,
        ReadOnlySpan<byte> aesKey)
    {
        InitializeKeys(publicId, privateId, aesKey);
        _cfgFlags |= ConfigFlag.StaticTicket;
    }
}

    /// <summary>
    ///     OATH-HOTP mode. Shares bit 0x40 with <see cref="ChalResp" />; the configuration flags decide
    ///     which mode the slot is in.
    /// </summary>
    OathHotp = 0x40,

    /// <summary>
    ///     Challenge-response mode. Shares bit 0x40 with <see cref="OathHotp" />.
    /// </summary>
    ChalResp = 0x40,

    /// <summary>
    ///     Set on slot 1: the YubiKey refuses to write slot 2 unless slot 2 is already configured with
    ///     this flag too. Not part of the update mask.
    /// </summary>
    ProtectSlot2 = 0x80
}

/// <summary>
/// Defines which <see cref="TicketFlag"/> values are valid for update operations.
/// </summary>
public static class TicketFlagMasks
{
    public const TicketFlag UpdateMask =
        TicketFlag.TabFirst |
        TicketFlag.AppendTab1 |
        TicketFlag.AppendTab2 |
        TicketFlag.AppendDelay1 |
        TicketFlag.AppendDelay2 |
        TicketFlag.AppendCr;
}

/// <summary>
/// Configures a slot for challenge-response mode using the Yubico OTP (AES-128) algorithm.
/// </summary>
/// <remarks>
/// This is distinct from <see cref="YubiOtpSlotConfiguration"/>, which configures a slot to
/// emit a Yubico OTP on touch. This configuration instead makes the slot respond to an
/// explicit 6-byte challenge sent via <see cref="YubiOtpSession.CalculateYubicoOtpAsync"/>,
/// returning a 16-byte AES-128 response.
/// <para>
/// The 16-byte AES key is stored directly in the <c>key</c> wire format field. The key must be
/// exactly 16 bytes; keys of any other length are rejected before any device I/O is attempted.
/// </para>

/// <summary>
/// Internal abstraction for YubiOTP transport-specific operations.
/// Implementations encode operations for SmartCard (APDU) or OTP HID (feature reports).
/// </summary>
/// <remarks>
/// Backends are pure users of the protocol they are handed: they own no disposable state and are
/// deliberately not <see cref="IDisposable" />. The session disposes the protocol through
/// <c>ApplicationSession</c>, and the connection is released by whoever created it. A backend that
/// ever needs to own a resource must revisit that ownership chain rather than add a disposal hook here.
/// </remarks>
internal interface IYubiOtpBackend
{
    /// <summary>
    /// Writes a configuration to a slot and returns the updated status bytes.
    /// Used for programming slots, swapping, deleting, setting scan maps, and NDEF configuration.
    /// </summary>
    /// <param name="slot">The config slot command byte.</param>
    /// <param name="data">The configuration data to write.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The updated status bytes from the YubiKey.</returns>
    ValueTask<ReadOnlyMemory<byte>> WriteUpdateAsync(
        ConfigSlot slot,
        ReadOnlyMemory<byte> data,
        CancellationToken cancellationToken);

    /// <summary>
    /// Sends data to a slot and receives a response of the expected length.
    /// Used for challenge-response and serial number read operations.
    /// </summary>
    /// <param name="slot">The config slot command byte.</param>
    /// <param name="data">The data to send (e.g., challenge bytes).</param>
    /// <param name="expectedLength">The expected response data length (excluding CRC).</param>
    /// <param name="userPresenceNotification">The non-null notification handle for the operation.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The response data from the YubiKey.</returns>
    ValueTask<ReadOnlyMemory<byte>> SendAndReceiveAsync(
        ConfigSlot slot,
        ReadOnlyMemory<byte> data,
        int expectedLength,
        UserPresenceNotification userPresenceNotification,
        CancellationToken cancellationToken);
}

    [Fact]
    public void Dispose_ZeroesAllConfigurationBuffers()
    {
        var configuration = new TestSlotConfiguration();
        configuration.WriteFixed(CreateFilledBuffer(YubiOtpConstants.FixedSize));
        configuration.WriteUid(CreateFilledBuffer(YubiOtpConstants.UidSize));
        configuration.WriteKey(CreateFilledBuffer(YubiOtpConstants.KeySize));

        byte[] fixedBuffer = GetBuffer(configuration, "_fixed");
        byte[] uidBuffer = GetBuffer(configuration, "_uid");
        byte[] keyBuffer = GetBuffer(configuration, "_key");

        configuration.Dispose();

        Assert.All(fixedBuffer, value => Assert.Equal(0, value));
        Assert.All(uidBuffer, value => Assert.Equal(0, value));
        Assert.All(keyBuffer, value => Assert.Equal(0, value));
    }

    private static FieldInfo GetField(string fieldName) =>
        typeof(SlotConfiguration).GetField(fieldName, BindingFlags.Instance | BindingFlags.NonPublic)
        ?? throw new InvalidOperationException($"SlotConfiguration field '{fieldName}' was not found.");

    private static byte[] GetBuffer(SlotConfiguration configuration, string fieldName) =>
        Assert.IsType<byte[]>(GetField(fieldName).GetValue(configuration));

    private static byte[] CreateFilledBuffer(int length)
    {
        var buffer = new byte[length];
        buffer.AsSpan().Fill(0xA5);
        return buffer;
    }

    private sealed class TestSlotConfiguration : SlotConfiguration
    {
        public void WriteFixed(ReadOnlySpan<byte> value) => SetFixed(value);

        public void WriteUid(ReadOnlySpan<byte> value) => SetUid(value);

        public void WriteKey(ReadOnlySpan<byte> value) => SetKey(value);
    }
}

[Fact]
public async Task CreateAsync_SmartCardBackendConstruction_PreservesProgrammingSequence()
{
    var connection = Substitute.For<ISmartCardConnection>();
    connection.Type.Returns(ConnectionType.SmartCard);
    connection.Transport.Returns(Transport.Usb);
    byte[] managementResponse = [.. "YubiKey 5.7.0"u8, 0x90, 0x00];
    byte[] otpResponse = [5, 7, 0, 9, 0, 0, 0x90, 0x00];
    connection.TransmitAndReceiveAsync(Arg.Any<ReadOnlyMemory<byte>>(), Arg.Any<CancellationToken>())
        .Returns(
            Task.FromResult((ReadOnlyMemory<byte>)managementResponse),
            Task.FromResult((ReadOnlyMemory<byte>)otpResponse));

    using var session = await YubiOtpSession.CreateAsync(
        connection,
        cancellationToken: TestContext.Current.CancellationToken);

    var backend = Assert.IsType<SmartCardBackend>(
        typeof(YubiOtpSession)
            .GetField("_backend", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(session));
    var programmingSequence = (byte)typeof(SmartCardBackend)
        .GetField("_lastProgSeq", BindingFlags.Instance | BindingFlags.NonPublic)!
        .GetValue(backend)!;

    Assert.Equal(9, programmingSequence);
}

public class HmacChallengeSemantics
{
    [Theory]
    [InlineData(new byte[0], (byte)0x00)]
    [InlineData(new byte[] { 0x41 }, (byte)0x00)]
    [InlineData(new byte[] { 0x41, 0x00 }, (byte)0x01)]
    [InlineData(new byte[] { 0x00 }, (byte)0x01)]
    [Trait("Audit", "YESDK-1659")]
    public async Task CalculateHmacSha1Async_ShortAndExplicitlyPaddedChallenges_SendIdenticalRequests(
        byte[] challenge, byte padByte)
    {
        var (connection, session) = await CreateFakeSessionAsync();
        using var sessionLease = session;
        List<byte[]> commands = [];
        connection.TransmitAndReceiveAsync(Arg.Any<ReadOnlyMemory<byte>>(), Arg.Any<CancellationToken>())
            .Returns(call =>
            {
                // Capture during transmission: the session clears its encoded challenge on return.
                commands.Add(call.ArgAt<ReadOnlyMemory<byte>>(0).ToArray());
                return Task.FromResult((ReadOnlyMemory<byte>)CreateApduResponseData(20));
            });
        byte[] explicitChallenge = [.. challenge, .. Enumerable.Repeat(padByte, 64 - challenge.Length)];

        _ = await session.CalculateHmacSha1Async(Slot.Two, challenge, TestContext.Current.CancellationToken);
        _ = await session.CalculateHmacSha1Async(Slot.Two, explicitChallenge, TestContext.Current.CancellationToken);

        Assert.Equal(2, commands.Count);
        Assert.Equal(commands[0], commands[1]);
        byte[] expectedCommand = [0x00, 0x01, 0x38, 0x00, 0x40, .. explicitChallenge, 0x00];
        Assert.Equal(expectedCommand, commands[0]);
        Assert.Equal(challenge, explicitChallenge[..challenge.Length]);
    }

    [Theory]
    [InlineData(63, (byte)0x00)]
    [InlineData(63, (byte)0x01)]
    [InlineData(64, (byte)0x00)]
    [InlineData(64, (byte)0x01)]
    [Trait("Audit", "YESDK-1659")]
    public async Task CalculateHmacSha1Async_AtShortAndFixedLengthBoundary_PreservesInputBytes(
        int length, byte lastByte)
    {
        var (connection, session) = await CreateFakeSessionAsync();
        using var sessionLease = session;
        byte[]? command = null;
        connection.TransmitAndReceiveAsync(Arg.Any<ReadOnlyMemory<byte>>(), Arg.Any<CancellationToken>())
            .Returns(call =>
            {
                command = call.ArgAt<ReadOnlyMemory<byte>>(0).ToArray();
                return Task.FromResult((ReadOnlyMemory<byte>)CreateApduResponseData(20));
            });
        byte[] challenge = [.. Enumerable.Range(1, length - 1).Select(i => (byte)i), lastByte];
        byte[] originalChallenge = [.. challenge];

        _ = await session.CalculateHmacSha1Async(Slot.One, challenge, TestContext.Current.CancellationToken);

        Assert.NotNull(command);
        Assert.Equal(70, command.Length);
        Assert.Equal(new byte[] { 0x00, 0x01, 0x30, 0x00, 0x40 }, command[..5]);
        Assert.Equal(originalChallenge, command[5..(5 + length)]);
        if (length == 63)
        {
            Assert.Equal(lastByte == 0x00 ? 0x01 : 0x00, command[68]);
        }
        Assert.Equal(0x00, command[69]);
        Assert.Equal(originalChallenge, challenge);
    }
}

[Fact]
public void YubiOtp_GetConfig_PlacesFieldsCorrectly()
{
    byte[] publicId = [0x01, 0x02, 0x03, 0x04, 0x05, 0x06];
    byte[] privateId = [0x10, 0x20, 0x30, 0x40, 0x50, 0x60];
    byte[] aesKey = [0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5, 0xA6, 0xA7,
                     0xA8, 0xA9, 0xAA, 0xAB, 0xAC, 0xAD, 0xAE, 0xAF];

    using var config = new YubiOtpSlotConfiguration(publicId, privateId, aesKey);
    var result = config.GetConfig();

    // fixed field: publicId padded with zeros
    Assert.Equal(publicId, result[FixedOffset..(FixedOffset + publicId.Length)]);
    Assert.All(result[(FixedOffset + publicId.Length)..UidOffset], b => Assert.Equal(0, b));

    // uid field: privateId
    Assert.Equal(privateId, result[UidOffset..(UidOffset + 6)]);

    // key field: aesKey
    Assert.Equal(aesKey, result[KeyOffset..(KeyOffset + 16)]);

    // fixed_size
    Assert.Equal(publicId.Length, result[FixedSizeOffset]);

    // acc_code: zeros
    Assert.All(result[AccCodeOffset..(AccCodeOffset + 6)], b => Assert.Equal(0, b));

    // RFU: zeros
    Assert.Equal(0, result[RfuOffset]);
    Assert.Equal(0, result[RfuOffset + 1]);
}

[Fact]
public void YubiOtp_GetConfig_WithAccessCode_PlacesAccessCode()
{
    byte[] publicId = [0x01, 0x02, 0x03, 0x04, 0x05, 0x06];
    byte[] privateId = new byte[6];
    byte[] aesKey = new byte[16];
    byte[] accCode = [0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF];

    using var config = new YubiOtpSlotConfiguration(publicId, privateId, aesKey);
    var result = config.GetConfig(accCode);

    Assert.Equal(accCode, result[AccCodeOffset..(AccCodeOffset + 6)]);
    AssertValidCrc(result);
}

[Fact]
public void StaticPassword_FromString_CopiesOwnedScanCodesBeforeZeroing()
{
    byte[] ownedScanCodes = [0x04, 0x05, 0x06];
    byte[] expectedScanCodes = [.. ownedScanCodes];

    using var config = new StaticPasswordSlotConfiguration(
        "abc",
        KeyboardLayout.en_US,
        (password, keyboardLayout) =>
        {
            Assert.Equal("abc", password);
            Assert.Equal(KeyboardLayout.en_US, keyboardLayout);
            return ownedScanCodes;
        });
    var result = config.GetConfig();

    Assert.Equal(expectedScanCodes, result[FixedOffset..(FixedOffset + expectedScanCodes.Length)]);
    Assert.All(ownedScanCodes, scanCode => Assert.Equal(0, scanCode));
}

[Fact]
public void StaticPassword_FromString_WhenInitializationFails_ZeroesOwnedScanCodes()
{
    byte[] ownedScanCodes = Enumerable.Repeat((byte)0x04, 39).ToArray();

    Assert.Throws<ArgumentException>(() =>
        new StaticPasswordSlotConfiguration(
            new string('a', 39),
            KeyboardLayout.en_US,
            (_, _) => ownedScanCodes));

    Assert.All(ownedScanCodes, scanCode => Assert.Equal(0, scanCode));
}

[Fact]
public void StaticPassword_FromRawScanCodes_DoesNotZeroCallerBuffer()
{
    byte[] callerOwnedScanCodes = [0x04, 0x05, 0x06];
    byte[] expectedScanCodes = [.. callerOwnedScanCodes];

    using var config = new StaticPasswordSlotConfiguration(callerOwnedScanCodes);

    Assert.Equal(expectedScanCodes, callerOwnedScanCodes);
}

[Fact]
public async Task SendAndReceiveAsync_WhenResolutionThrowsAfterValidation_PropagatesResolutionException()
{
    byte[] responseWithCrc = MakeResponseWithCrc(new byte[20]);
    var expected = new InvalidOperationException("resolution failed");
    var prompt = new ThrowingPrompt(resolutionException: expected);
    UserPresenceContext context = CreateContext();
    ConfigurePresenceResponse(responseWithCrc);
    var backend = new HidBackend(_protocol);
    UserPresenceNotification notification = UserPresenceNotification.Create(prompt, context);

    InvalidOperationException actual = await Assert.ThrowsAsync<InvalidOperationException>(() =>
        backend.SendAndReceiveAsync(
            ConfigSlot.ChalHmac1,
            new byte[64],
            20,
            notification,
            TestContext.Current.CancellationToken).AsTask());

    Assert.Same(expected, actual);
    Assert.All(responseWithCrc, value => Assert.Equal(0, value));
}

