[Fact]
public async Task SendAndReceiveAsync_YubicoOtpChallenge_TransmitsExactChallengeBytesUnpadded()
{
    byte[] challenge = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66];
    byte[] responseData = new byte[18]; // 16 bytes + SW
    responseData[^2] = 0x90;
    responseData[^1] = 0x00;
    var response = new ApduResponse(responseData);

    _protocol.TransmitAndReceiveAsync(
            Arg.Any<ApduCommand>(),
            Arg.Any<bool>(),
            Arg.Any<CancellationToken>())
        .Returns(Task.FromResult(response));

    var backend = CreateBackend();
    await backend.SendAndReceiveAsync(
        ConfigSlot.ChalYubico1,
        challenge,
        16,
        UserPresenceNotification.None,
        cancellationToken: CancellationToken.None);

    await _protocol.Received(1).TransmitAndReceiveAsync(
        Arg.Is<ApduCommand>(a =>
            a.P1 == (byte)ConfigSlot.ChalYubico1 &&
            a.Data.ToArray().SequenceEqual(challenge)),
        Arg.Any<bool>(),
        Arg.Any<CancellationToken>());
}

/// <summary>
///     Pins the ownership contract: YubiOTP backends borrow the protocol handed to them and own no
///     disposable state, so neither the abstraction nor its implementations advertise <see cref="IDisposable" />.
///     Disposal belongs to the session (protocol) and to whoever created the connection.
/// </summary>
public class YubiOtpBackendLifecycleTests
{
    [Fact]
    public void IYubiOtpBackend_DoesNotAdvertiseResourceOwnership()
    {
        Assert.False(typeof(IDisposable).IsAssignableFrom(typeof(IYubiOtpBackend)));
    }

    [Fact]
    public void SmartCardBackend_DoesNotAdvertiseResourceOwnership()
    {
        Assert.False(typeof(IDisposable).IsAssignableFrom(typeof(SmartCardBackend)));
    }

    [Fact]
    public void HidBackend_DoesNotAdvertiseResourceOwnership()
    {
        Assert.False(typeof(IDisposable).IsAssignableFrom(typeof(HidBackend)));
    }
}

    ConfigState configuredState = session.GetConfigState();
    Assert.True(configuredState.IsConfigured(Slot.Two));
    output.WriteLine(
        $"Post-configuration status: Slot2IsTouchTriggered={configuredState.IsTouchTriggered(Slot.Two)} " +
        "(reported for inspection; HID wait behavior is authoritative for this probe).");

    Assert.Empty(prompt.Requested);
    Assert.Empty(prompt.Resolved);
    expectedResponse = HMACSHA1.HashData(key, challenge);

    using var operationCts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
    response = await session.CalculateHmacSha1Async(Slot.Two, challenge, operationCts.Token);

    Assert.True(CryptographicOperations.FixedTimeEquals(expectedResponse, response.Span));

    UserPresenceContext requested = Assert.Single(prompt.Requested);
    Assert.Equal(UserPresenceBasis.DeviceWaiting, requested.Basis);
    Assert.Equal("YubiOTP", requested.Application);
    Assert.Equal(Slot.Two.ToString(), requested.Scope);

    (UserPresenceContext Context, UserPresenceOutcome Outcome, CancellationToken CancellationToken) resolved =
        Assert.Single(prompt.Resolved);
    Assert.Same(requested, resolved.Context);
    Assert.Equal(UserPresenceOutcome.Completed, resolved.Outcome);
    Assert.Equal(CancellationToken.None, resolved.CancellationToken);
}
finally
{
    if (!response.IsEmpty)
    {
        CryptographicOperations.ZeroMemory(MemoryMarshal.AsMemory(response).Span);
    }

    if (expectedResponse is not null)
    {
        CryptographicOperations.ZeroMemory(expectedResponse);
    }

    CryptographicOperations.ZeroMemory(challenge);
    CryptographicOperations.ZeroMemory(key);

    if (slotCreated)
    {
        await session.DeleteSlotAsync(Slot.Two);
        Assert.False(session.GetConfigState().IsConfigured(Slot.Two));
        output.WriteLine("Cleanup: deleted the test-created configuration from YubiOTP slot 2.");
    }
}

/// <summary>
/// Encodes a device serial number as a 6-byte public ID.
/// The serial is stored as big-endian in the last 4 bytes, with 2 zero prefix bytes.
/// </summary>
private static byte[] EncodeSerialAsPublicId(int serial)
{
    byte[] publicId = new byte[6];
    // Big-endian encoding of serial in bytes 2-5
    publicId[2] = (byte)((serial >> 24) & 0xFF);
    publicId[3] = (byte)((serial >> 16) & 0xFF);
    publicId[4] = (byte)((serial >> 8) & 0xFF);
    publicId[5] = (byte)(serial & 0xFF);
    return publicId;
}

private static void DisplayStatus(ConfigState state)
{
    OutputHelper.WriteHeader("OTP Slot Status");

    OutputHelper.WriteKeyValue("Firmware", state.FirmwareVersion.ToString());
    AnsiConsole.WriteLine();

    var table = new Table()
        .Border(TableBorder.Rounded)
        .BorderColor(Color.Grey)
        .AddColumn(new TableColumn("[green]Property[/]"))
        .AddColumn(new TableColumn("[green]Slot 1[/]"))
        .AddColumn(new TableColumn("[green]Slot 2[/]"));

    try
    {
        table.AddRow(
            "Configured",
            FormatBool(state.IsConfigured(Slot.One)),
            FormatBool(state.IsConfigured(Slot.Two)));
    }
    catch (InvalidOperationException)
    {
        table.AddRow("Configured", "[grey]N/A (fw < 2.1)[/]", "[grey]N/A (fw < 2.1)[/]");
    }

    try
    {
        table.AddRow(
            "Touch Triggered",
            FormatBool(state.IsTouchTriggered(Slot.One)),
            FormatBool(state.IsTouchTriggered(Slot.Two)));
    }
    catch (InvalidOperationException)
    {
        table.AddRow("Touch Triggered", "[grey]N/A (fw < 3.0)[/]", "[grey]N/A (fw < 3.0)[/]");
    }

    table.AddRow("LED Inverted", FormatBool(state.IsLedInverted()), "");

    AnsiConsole.Write(table);
}

private static object BuildStatusResult(ConfigState state)
{
    bool? slot1Configured = null;
    bool? slot2Configured = null;
    bool? slot1Touch = null;
    bool? slot2Touch = null;

    try
    {
        slot1Configured = state.IsConfigured(Slot.One);
        slot2Configured = state.IsConfigured(Slot.Two);
    }
    catch (InvalidOperationException) { }

    try
    {
        slot1Touch = state.IsTouchTriggered(Slot.One);
        slot2Touch = state.IsTouchTriggered(Slot.Two);
    }
    catch (InvalidOperationException) { }

    return new
    {
        firmware = state.FirmwareVersion.ToString(),
        slot1 = new
        {
            configured = slot1Configured,
            touchTriggered = slot1Touch
        },
        slot2 = new
        {
            configured = slot2Configured,
            touchTriggered = slot2Touch
        },
        ledInverted = state.IsLedInverted()
    };
}
